const blank=()=>({view:'landing',joinStep:1,actor:'member',member:{name:'',contact:'',photo:'',answers:[],agreed:false},prospect:{name:'',phone:'',email:'',photo:'',answers:[],agreed:false},connectionId:'',liveInvite:false,liveToken:'',liveMember:false,liveId:'',inbox:[],memberQuestionsOpen:false,prospectQuestionsOpen:false,phase:'registration',index:0,pick:null,modal:'',messages:[],notice:'',testRequest:'',memberId:'',prospectId:'',resumePhase:'',outgoing:[],selectedOutgoing:'',selectedChempat:'',secretsFor:'',qrInvite:null,qrError:'',signinEmail:'',codeSentAt:0,codeSentTo:'',verifyEmail:'',qrNeedsVerify:false,prospectVerified:null,friends:[],friendToken:'',friendInvite:null,friendError:'',friendAcceptedId:'',friendShare:null,friendShareError:'',friendVibeState:null});
