function selectChempat(id,showSecrets=false){const input=$('message')||$('outgoingMessage');if(input)rememberChatText(input.value);const chosen=memberConnections().find(c=>c.id===id);if(!chosen)return;s.selectedChempat=id;if(isFriend(chosen)&&s.view!=='dashboard')s.view='dashboard';s.secretsFor=showSecrets&&!isFriend(chosen)?id:'';if(!isFriend(chosen)){if(s.liveMember){const c=s.inbox.find(item=>item.id===id);if(c){s.liveId=id;applyConnection(c)}}else if(s.actor==='prospect'&&id!=='first')s.selectedOutgoing=id}render()}
function selectPrivateChat(id){const c=memberConnections().find(item=>item.id===id);if(!c||!chatOpen(c.status))return;selectChempat(id);($('message')||$('outgoingMessage'))?.focus()}
function normalizeConnection(c){return {id:c.id,kind:isFriend(c)?'friend':'vibe',name:first(c.side==='prospect'?c.sender_name:c.prospect_name||c.recipient_name||'Someone'),photo:c.side==='prospect'?c.sender_photo:c.prospect_photo||'',status:c.status,side:c.side==='prospect'?'received':'sent',invitedAt:c.invitedAt,sharedEmail:isFriend(c)?'':c.side==='prospect'?'':c.prospect_email,channel:c.channel,claimed:c.claimed,ownSecondDone:c.side==='prospect'?c.prospectSecondDone:c.memberSecondDone,otherSecondDone:c.side==='prospect'?c.memberSecondDone:c.prospectSecondDone,ownAnswers:isFriend(c)?[]:c.own_answers,messages:c.messages||[],answers:isFriend(c)?[]:c.side==='prospect'?c.sender_answers||[]:c.prospect_answers||[]}}
