function renderFriendShare(){const invite=s.friendShare,expired=invite&&new Date(invite.expiresAt).getTime()<=Date.now();$('modalHost').innerHTML=`<div class="modalBackdrop" onclick="closeInvite(event)"><section class="modal friendShareModal" role="dialog" aria-modal="true" aria-labelledby="friendShareTitle"><button class="close" type="button" aria-label="Close" onclick="closeInvite()">×</button><div class="eyebrow">INVITE A FRIEND</div><h2 id="friendShareTitle">Come try Chem-patible with me.</h2>${invite&&!expired?`<p>Your friend invitation is on its way.</p><div class="friendSentCard"><b>${esc(invite.recipient?.name||'Friend')}</b><span>${esc(invite.recipient?.email||'')}</span><small>INVITE CODE</small><strong>${esc(invite.code||'')}</strong></div><label class="field">Friend invitation link<input id="friendShareLink" readonly value="${esc(invite.url)}" onclick="this.select()"></label><p class="small">One use · expires ${esc(new Date(invite.expiresAt).toLocaleString())}.</p>${navigator.share?button('Share invitation','shareFriendInvitation()'):''}${button('Copy invitation','copyFriendInvitation()','light')}`:`<p>Send this to someone you already know. They’ll connect as your friend and go straight to private chat — no dating questions.</p><label class="field">Friend’s name<input id="friendName" autocomplete="given-name" maxlength="50" placeholder="First name" value="${esc(s.friendShareDraft?.name||'')}"></label><label class="field">Friend’s email<input id="friendEmail" type="email" autocomplete="email" placeholder="friend@example.com" value="${esc(s.friendShareDraft?.email||'')}"></label>${sharingFriend?.state===s?'<p role="status">Sending your invitation…</p>':button('SEND FRIEND INVITATION →','makeFriendInvitation()')}`}<p class="error" id="friendShareError" role="alert">${esc(s.friendShareError)}</p><p class="small" id="friendShareStatus" role="status"></p></section></div>`}
